package org.example;

public class Wiki {
    public String link(String page) {
        return "/wiki/" + page;
    }
}

package org.example;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class WikiTest {
    @Test
    void forwards() {
        assertEquals("/wiki/Home", new Wiki().link("Home"));
    }
}

